public class LocalDate_fromCalendarFields_TriageGen0Test {



    @Test
    public void testFromCalendarFields_BC() {
        // Test for BC era logic: (1 - yearOfEra)
        // Note: In Calendar, BCE/BC is often represented by ERA != AD
        Calendar calendar = new GregorianCalendar();
        calendar.set(100, Calendar.JANUARY, 1);
        calendar.set(Calendar.ERA, GregorianCalendar.BC);

        // Based on logic: (era == AD ? yearOfEra : 1 - yearOfEra)
        // If era is BC, year = 1 - 100 = -99
        LocalDate expected = new LocalDate(-99, 1, 1);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals("Should correctly convert BC calendar to LocalDate", expected, actual);
    }




}

